def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c_total = sum(1 for a in opp if a == 'C')
    opp_ratio = opp_c_total / n

    recent_len = min(12, n)
    recent = opp[n - recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    # Opponent appears to always cooperate: keep cooperating but test sparingly
    if opp_ratio >= 0.97 and n >= 4:
        if n % 23 == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent appears to always defect: punish, with rare probes
    if opp_ratio <= 0.04 and n >= 4:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Heavy defector in recent window: mostly punish
    if recent_ratio <= 0.15 and recent_len >= 6:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Strongly cooperative opponent: cooperate, rarely probe
    if recent_ratio >= 0.85:
        if n % 19 == 0 and rng.random() < 0.06:
            return 'D'
        return 'C'

    last_opp = opp[-1]
    last_me = me[-1]

    # Count consecutive defections from opponent
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec_d += 1
        else:
            break

    # If opponent just defected after we cooperated (exploitation of our C)
    if last_opp == 'D' and last_me == 'C':
        if consec_d >= 3:
            return 'D' if rng.random() < 0.9 else 'C'
        if recent_ratio >= 0.55:
            # Likely a mistake / probe on their side: forgive often
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        # Mid-range: retaliate once, sometimes forgive
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Mutual defection: try to escape the trap
    if last_opp == 'D' and last_me == 'D':
        if consec_d >= 4:
            # Stuck in DD; try cooperating to reset
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if recent_ratio > 0.35:
            return 'C'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if last_opp == 'C':
        # Detect CC→D exploitation pattern from us; avoid over-defecting
        if n >= 3 and me[-3:] == ['C', 'C', 'D'] and opp[-3:] == ['C', 'C', 'C']:
            return 'C'
        return 'C'

    return 'C'
